From 1b45fe6454bc2cbc2a14999c71291feab9b211d8 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:13:47 +0100
Subject: [PATCH] desktoppackage/configuration: only offer scroll-capable mouse
 actions

Scroll triggers could be set to actions like Standard Menu or Application
Launcher, which do nothing on scroll. Scroll rows now only list actions
that support it, and new scroll triggers default to Switch Desktop.

BUG: 357367
---
 .../ConfigurationContainmentActions.qml        | 18 +++++++++++++++---
 1 file changed, 15 insertions(+), 3 deletions(-)

diff --git a/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml b/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml
index 5cac407e79..479cd36ba6 100644
--- a/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml
+++ b/desktoppackage/contents/configuration/ConfigurationContainmentActions.qml
@@ -31,6 +31,13 @@ KCM.SimpleKCM {
         "MetaModifier": i18ndc("plasma_shell_org.kde.plasma.desktop", "@label for shortcuts", "Meta")
     }

+    function pluginForTrigger(trigger, pluginName) {
+        if (trigger.startsWith("wheel:") && !configDialog.wheelContainmentActions.includes(pluginName)) {
+            return "org.kde.switchdesktop";
+        }
+        return pluginName;
+    }
+
     function saveConfig() {
         configDialog.currentContainmentActionsModel.save();
     }
@@ -73,7 +80,7 @@ KCM.SimpleKCM {
                 }
                 eventString: model.action
                 onEventStringChanged: {
-                    configDialog.currentContainmentActionsModel.update(index, eventString, model.pluginName);
+                    configDialog.currentContainmentActionsModel.update(index, eventString, root.pluginForTrigger(eventString, model.pluginName));
                 }
             }
         }
@@ -93,7 +100,10 @@ KCM.SimpleKCM {
                 // each other for available space. By setting an insane preferredWidth we give
                 // ComboBox a greater share of the available space
                 Layout.preferredWidth: 9000
-                model: configDialog.containmentActionConfigModel
+                readonly property string currentPlugin: pluginName
+                model: action.startsWith("wheel:")
+                    ? Array.prototype.filter.call(configDialog.containmentActionConfigModel.categories, category => configDialog.wheelContainmentActions.includes(category.pluginName))
+                    : configDialog.containmentActionConfigModel
                 textRole: "name"
                 valueRole: "pluginName"
                 property bool initialized: false
@@ -101,6 +111,8 @@ KCM.SimpleKCM {
                     currentIndex = indexOfValue(pluginName)
                     pluginsCombo.initialized = true;
                 }
+                onModelChanged: currentIndex = indexOfValue(currentPlugin)
+                onCurrentPluginChanged: currentIndex = indexOfValue(currentPlugin)
                 onActivated: {
                     if (initialized) {
                         var newPluginName = currentValue;
@@ -139,7 +151,7 @@ KCM.SimpleKCM {
             defaultText: i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:button", "Add Action");
             icon.name: checked ? "input-mouse-symbolic" : "list-add"
             onEventStringChanged: {
-                configDialog.currentContainmentActionsModel.append(eventString, "org.kde.contextmenu");
+                configDialog.currentContainmentActionsModel.append(eventString, root.pluginForTrigger(eventString, "org.kde.contextmenu"));
             }
         }
     }
-- 
